package com.ecotwin.model;
import jakarta.persistence.*;import java.time.LocalDate;
@Entity @Table(name="devices") public class Device { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; @Column(nullable=false) private String name; private String type; private LocalDate purchaseDate; private String status="ACTIVE"; private Integer ets=80, eli=75, ess=70; private String passportId; public Device(){} public Device(String name,String type,LocalDate purchaseDate){this.name=name;this.type=type;this.purchaseDate=purchaseDate;this.passportId="ETP-"+name.replaceAll("[^A-Za-z0-9]","").toUpperCase().substring(0,Math.min(5,name.replaceAll("[^A-Za-z0-9]","").length()))+"-"+System.currentTimeMillis()%10000;} public String getId(){return id;} public String getName(){return name;} public String getType(){return type;} public LocalDate getPurchaseDate(){return purchaseDate;} public String getStatus(){return status;} public Integer getEts(){return ets;} public Integer getEli(){return eli;} public Integer getEss(){return ess;} public String getPassportId(){return passportId;} public void setName(String v){name=v;} public void setType(String v){type=v;} public void setPurchaseDate(LocalDate v){purchaseDate=v;} }
